import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

it('reports a rejected string with its cause while preserving the caller rejection', async () => {
  const rejection = 'string boom';
  const errors: Error[] = [];
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'Assistant'}),
    undefined,
    {
      hooks: {
        beforeSession: () => Promise.reject(rejection),
        onError: async (_session, error) => {
          errors.push(error);
        },
      },
    }
  );

  const outcome: unknown = await orchestrator.processMessage(session).catch((error: unknown) => error);

  expect({outcome, errors}).toEqual({
    outcome: rejection,
    errors: [expect.objectContaining({message: rejection, cause: rejection})],
  });
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/onErrorString.test.ts --runInBand"
